"""Generate the human-readable Stage 0 report from the audited counts."""

import re
from pathlib import Path


def write_report(output: Path, summary: dict, config: dict) -> None:
    lines = ["# Stage 0 data and station identity audit", "",
             "Generated by `python scripts/run_stage0.py`. No treatment effects or radius "
             "feasibility counts have been estimated. Trip counts below precede panel exclusions "
             "for short and same-station trips.", "", "## Annual trips", "",
             "| Year | Raw published trips | Missing endpoint | Virtual endpoint | Retained |",
             "| --- | ---: | ---: | ---: | ---: |"]
    for year, counts in summary["annual_trip_counts"].items():
        lines.append(f"| {year} | {counts['raw_rows']:,} | {counts['missing_station_rows']:,} | "
                     f"{counts['virtual_station_rows']:,} | {counts['retained_rows']:,} |")
    lines += ["", "## Station inventory and observation dates", "",
              f"Official table: [{summary['station_table']}]({summary['station_table_source_url']}). "
              f"It has {summary['station_table_rows_including_virtual']} nonblank IDs including "
              f"virtual station 3000, or {summary['station_table_stations_excluding_virtual']} "
              f"nonvirtual IDs. The study trip files contain "
              f"{summary['observed_stations_excluding_virtual']} observed IDs. Station-ID counts "
              "are not counts of distinct physical openings.", "",
              "Both departures and arrivals enter the first and last observed trip dates in "
              "`opening_date_audit.csv`. These are local calendar dates. Earlier-than-official "
              "first trips take precedence even within the date tolerance; exactly +14 days "
              "uses the official date, and +15 days requires review.", "",
              "| Case | All observed IDs | Official openings in 2022–2024, observed |",
              "| --- | ---: | ---: | ---: |"]
    for case in ("within_tolerance", "first_trip_earlier", "first_trip_late_review"):
        lines.append(f"| {case} | {summary['date_cases_all_comparable_observed'].get(case, 0)} | "
                     f"{summary['date_cases_official_openings_2022_2024'].get(case, 0)} |")
    statuses = summary["date_status_counts"]
    lines += ["", f"{statuses.get('left_censored_pre_window', 0)} pre-window stations are "
              "left-censored; retain their official dates rather than interpreting their first "
              "2022 trip as an opening. "
              f"{statuses.get('unobserved_in_trip_window', 0)} table IDs have no trip in the "
              "study files and are not comparable to an observed first trip. Unresolved opening "
              f"dates requiring review: {summary['manual_review_station_count']}.", "",
              "## Coordinate support and relocation", "",
              f"Use at least {summary['min_trips_per_quarter_coordinate']} valid paired departure "
              "coordinates in a quarter before its median can enter a distance or relocation "
              f"check. The raw medians of {summary['low_support_station_quarters']} rejected "
              "station-quarters remain in `quarterly_coordinates.csv` with `coordinate_usable=False`. "
              "Low-support coordinates do not enter identity matching or representative centers.", "",
              f"Distances use {summary['projected_crs']} in metres. A displacement must exceed "
              f"{summary['relocation_threshold_m']} metres across supported quarters to trigger "
              f"a relocation flag. **Flagged within-ID stations: "
              f"{summary['relocation_flagged_station_count']}.** IDs with fewer than two supported "
              "quarters remain explicitly unaudited for relocation. Missing coordinates never "
              "become zero distance.", "", "## Candidate discovery and classification", "",
              f"Name matching found **{summary['station_identity_name_pairs']} pairs**. The "
              "name-independent distance and retirement-date check added "
              f"**{summary['station_identity_additional_proximity_pairs']} pairs**, for "
              f"**{summary['station_identity_candidate_pairs']} distinct pairs**. A pair found "
              "by both checks is counted in the name column only.", "",
              f"The extra check requires distance <= {config['identity']['replacement_distance_m']} "
              "metres and the earlier ID's last trip within "
              f"+/-{config['identity']['proximity_retirement_window_days']} days of the later "
              "ID's reconciled opening date. Earlier IDs need not predate 2022. See "
              "`station_identity_candidates.csv` for both names, distances, date ranges, signed "
              "handoff gaps, overlap days, rule decisions, and final component exclusions.", "",
              "| Classification | Name-based pairs | Additional proximity pairs | Total |",
              "| --- | ---: | ---: | ---: |"]
    by_source = summary["identity_pair_counts_by_discovery"]
    for case, name_count in by_source["name"].items():
        proximity_count = by_source["proximity_only"][case]
        lines.append(f"| {case} | {name_count} | {proximity_count} | {name_count + proximity_count} |")
    lines += ["", "Operation overlap is the intersection of the two observed first/last-date "
              f"intervals in calendar days. More than {config['identity']['max_overlap_days']} "
              "days takes priority over handoff merging. Exactly "
              f"{config['identity']['max_overlap_days']} overlap days or an absolute handoff "
              f"gap of exactly {config['identity']['max_handoff_gap_days']} days remains eligible "
              "for renumbering. A positive gap above "
              f"{config['identity']['max_handoff_gap_days']} days is an interrupted reopening. "
              "Missing coordinates, relocation, concurrency, and unresolved timelines exclude "
              "both identities from station pools. A merge preserves the earliest ID and opening "
              "date. Exclusions propagate through approved merge chains; conflicting predecessor "
              "identities are excluded without fusing distinct stations.", "",
              "## Remaining physical openings", "",
              f"Start with **{summary['original_opening_ids_2022_2024']} observed opening IDs** "
              "whose reconciled dates are in 2022–2024. The complete reconciliation is "
              "`opening_identity_screening.csv`:", "",
              "| Screening result | Raw opening IDs |", "| --- | ---: |"]
    for case in ("merged_replacement", "excluded_identity", "retained_new_station"):
        lines.append(f"| {case} | {summary['opening_id_screening_counts'].get(case, 0)} |")
    lines += ["", f"**Retained canonical physical openings in 2022–2024: "
              f"{summary['retained_physical_openings_2022_2024']}.** "
              f"Of these, **{summary['retained_treatment_source_openings']}** fall in the "
              f"narrower {config['study']['treatment_opening_start']} through "
              f"{config['study']['treatment_opening_end']} treatment-source window. "
              "Lists are in `new_stations.csv` and `treatment_source_stations.csv`. These are "
              "the surviving openings under the preregistered identity rules, not independent "
              "operational verification of every physical site.", "",
              "| Reconciled opening year | Retained canonical openings |", "| --- | ---: |"]
    for year, count in summary["retained_physical_openings_by_year"].items():
        lines.append(f"| {year} | {count} |")
    lines += ["", "## Continuous station identities and conservation", "",
              f"`station_id_map.csv` maps all {summary['identity_mapping_rows']} raw nonvirtual "
              f"IDs to {summary['canonical_station_rows']} canonical station records. "
              "`canonical_station_registry.csv` preserves membership, earliest opening, first/last "
              "activity, and explicit identity exclusion reasons. Identity-cleared pre-2022 status "
              "does not yet assert that baseline volume or inactivity criteria have passed.", "",
              "`load_trips(..., station_id_map=...)` remaps both endpoints before later "
              "same-physical-station cleaning. Excluded endpoints do not erase valid departures "
              "from another station. The ignored `data/interim/identity_weekly_departures.csv` "
              "combines aliases and includes zero weeks across interruptions. It is an identity "
              "activity audit, before short/round-trip panel cleaning; apply the inactivity "
              "rule only to the continuous identity. The canonical weekly grid has "
              f"{summary['identity_weekly_rows']:,} rows and preserves "
              f"{summary['identity_weekly_departures_sum']:,} departures within the complete-week "
              "study window, enforced by a failing assertion.", "",
              "## Reproduction", "", "```powershell", "python -m pip install -e '.[dev]'",
              "python scripts/run_stage0.py", "```", "",
              "Use `--offline` for already downloaded inputs; checksums are verified before "
              "auditing. URLs and SHA256 hashes for archives and extracted CSVs remain pinned "
              "in `data/manifest.json`. Source discovery uses Indego's official public media "
              "catalog because its data-page HTML lists stale 2017 links. Raw and intermediate "
              "inputs stay outside Git. No radius counting or treatment-effect fitting is "
              "performed by this command.", ""]
    (output / "README.md").write_text("\n".join(lines), encoding="utf-8")
    readme_path = output.parents[1] / "README.md"
    if readme_path.exists():
        readme = readme_path.read_text(encoding="utf-8")
        generated = (
            "<!-- stage0-summary:start -->\n"
            f"Stage 0 found {summary['station_identity_name_pairs']} name-based identity pairs and "
            f"{summary['station_identity_additional_proximity_pairs']} additional proximity/timing pairs. "
            f"The identity rules retain {summary['retained_physical_openings_2022_2024']} canonical "
            f"openings in 2022–2024, including {summary['retained_treatment_source_openings']} in the "
            "treatment-source window. "
            f"{statuses.get('unobserved_in_trip_window', 0)} station-table IDs have no observed trip "
            "in the study files and are reported separately from opening-date discrepancies.\n"
            "<!-- stage0-summary:end -->"
        )
        readme = re.sub(r"<!-- stage0-summary:start -->.*?<!-- stage0-summary:end -->",
                        lambda match: generated, readme, flags=re.DOTALL)
        readme_path.write_text(readme, encoding="utf-8")
